CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS benchmark_suites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug varchar(100) NOT NULL,name varchar(200) NOT NULL,description text NOT NULL,version varchar(30) NOT NULL,category varchar(80) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(slug,version));
CREATE TABLE IF NOT EXISTS benchmark_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),suite_id uuid NOT NULL REFERENCES benchmark_suites(id) ON DELETE CASCADE,task_key varchar(100) NOT NULL,title varchar(250) NOT NULL,category varchar(80) NOT NULL,prompt text NOT NULL,target_version varchar(80),expected jsonb NOT NULL,rubric jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(suite_id,task_key));
CREATE TABLE IF NOT EXISTS agent_configs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(150) NOT NULL,mode varchar(30) NOT NULL CHECK(mode IN('baseline','research')),model varchar(200) NOT NULL,settings jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS benchmark_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),suite_id uuid NOT NULL REFERENCES benchmark_suites(id),agent_config_id uuid NOT NULL REFERENCES agent_configs(id),status varchar(30) NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','completed','failed','partially_completed')),total_tasks integer NOT NULL CHECK(total_tasks>=0),completed_tasks integer NOT NULL DEFAULT 0 CHECK(completed_tasks>=0),aggregate_score numeric(6,2),started_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS benchmark_runs_created_idx ON benchmark_runs(created_at DESC);CREATE INDEX IF NOT EXISTS benchmark_runs_status_idx ON benchmark_runs(status);
CREATE TABLE IF NOT EXISTS task_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid NOT NULL REFERENCES benchmark_runs(id) ON DELETE CASCADE,task_id uuid NOT NULL REFERENCES benchmark_tasks(id),status varchar(30) NOT NULL DEFAULT 'running' CHECK(status IN('running','completed','failed')),answer text,claims jsonb DEFAULT '[]'::jsonb,metrics jsonb DEFAULT '{}'::jsonb,score numeric(6,2),latency_ms integer,input_tokens integer,output_tokens integer,error text,started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(run_id,task_id));CREATE INDEX IF NOT EXISTS task_attempts_run_idx ON task_attempts(run_id);
CREATE TABLE IF NOT EXISTS evidence_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid NOT NULL REFERENCES task_attempts(id) ON DELETE CASCADE,url text NOT NULL,title text,snippet text,content_hash varchar(64),retrieved_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,is_official boolean NOT NULL DEFAULT false);